function validate([firstWord, secondWord, targetWord]) {
  for (const word of [firstWord, secondWord, targetWord]) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 8) return 'Each word has 1 to 8 letters.';
    if (!/^[a-j]+$/.test(word)) return "Words use only the letters 'a' to 'j'.";
  }
  return null;
}

