function isSumEqual(firstWord, secondWord, targetWord) {
  function wordValue(word) {
    let value = 0;
    for (const letter of word) {
      const digit = letter.charCodeAt(0) - 'a'.charCodeAt(0);
      value = value * 10 + digit;
    }
    return value;
  }
  const sum = wordValue(firstWord) + wordValue(secondWord);
  return sum === wordValue(targetWord);
}

