function isSumEqual(firstWord, secondWord, targetWord) {
  const letters = 'abcdefghij';
  const asNumber = (word) => Number(word.split('').map(c => letters.indexOf(c)).join(''));
  return asNumber(firstWord) + asNumber(secondWord) === asNumber(targetWord);
}

