function generate(rand, size) {
  const letters = 'abcdefghij';
  const maxLength = size === 'large' ? 8 : 4;
  const word = (length) => Array.from({ length }, () => letters[Math.floor(rand() * 10)]).join('');
  const randomLength = () => (size === 'large' && rand() < 0.6 ? 8 : 1 + Math.floor(rand() * maxLength));
  const firstWord = word(randomLength());
  const secondWord = word(randomLength());
  let targetWord = word(randomLength());
  if (rand() < 0.5) {
    // Build the matching target so that true answers are common.
    const value = (w) => Number(w.split('').map(c => letters.indexOf(c)).join(''));
    let digits = String(value(firstWord) + value(secondWord));
    while (digits.length < 8 && rand() < 0.3) digits = '0' + digits;
    if (digits.length <= 8) targetWord = digits.split('').map(d => letters[Number(d)]).join('');
  }
  return [firstWord, secondWord, targetWord];
}
